-- Boss élites rares de donjon (généré)
SET NAMES utf8mb4;
DELETE FROM creature_linking WHERE guid BETWEEN 9902000 AND 9902099;
DELETE FROM creature_movement WHERE Id BETWEEN 9902000 AND 9902099;
DELETE FROM creature WHERE guid BETWEEN 9902000 AND 9902099;
DELETE FROM creature_template WHERE Entry BETWEEN 990400 AND 990419;
DELETE FROM creature_loot_template WHERE entry BETWEEN 990400 AND 990459;
DELETE FROM creature_spell_list WHERE Id BETWEEN 990400 AND 990419;
DELETE FROM creature_spell_list_entry WHERE Id BETWEEN 990400 AND 990419;
DELETE FROM reference_loot_template WHERE entry BETWEEN 993399 AND 993499;
DELETE FROM item_template WHERE entry BETWEEN 995000 AND 995999;

-- Épiques « sublimes » : bleus du monde passés en épique (stats x1,2) pour les bas niveaux
